// 1. Criar as Unidades
CREATE (u1:Unidade {nome:'Metalúrgica Brasilfer Ltda', grupo_empresarial:'Brasilfer'}),
  (u2:Unidade {nome:'Construtora Horizonte S.A.', grupo_empresarial:'Horizonte'}),
  (u3:Unidade {nome:'Agroquímica Verde Campo Eireli', grupo_empresarial:'Verde Campo'});

// 6. GrupoTreinamento POSSUI Evento
MATCH  (g:GrupoTreinamento)
MATCH  (e:Evento)
WHERE  g.id_grupo = e.id_evento
CREATE  (g)-[:POSSUI]->(e);

// 8. Evento REALIZA Treinamento
MATCH  (e:Evento)
MATCH  (t:Treinamento)
WHERE  e.id_evento = t.id_treinamento
CREATE  (e)-[:REALIZA]->(t);

// 10. Treinamento RECEBE Certificado
MATCH  (t:Treinamento)
MATCH  (cert:Certificado)
WHERE  t.id_treinamento = cert.id_certificado
CREATE  (t)-[:RECEBE]->(cert);
